import { createRuntime } from '@migaia/reactive'

const runtime = createRuntime()

const count = runtime.signal(1)
const doubled = runtime.computed(() => count.value * 2)

const seen: number[] = []
const effect = runtime.effect(() => {
  seen.push(doubled.value)
}) // 创建时立即同步跑一次：seen = [2]

