  })
} catch (error) {
  // error 就是 'business failure' 本身；若收尾 flush 也失败，flush 错误挂在 error.cause 上
}

const runtime = createRuntime({
  schedulerStrategy: (flush) => {
    requestAnimationFrame(() => flush())
  }
})

